// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address target, bytes calldata data) public {
        // fuzz arbitrary target and data to trigger the onERC721Received callback
        vm.assume(target != address(0));
        vm.assume(target.code.length == 0); // EOA or precompile will not implement the interface

        // Deploy a helper that calls onERC721Received and checks the returned selector
        CallbackChecker checker = new CallbackChecker(c);
        bytes4 returned = checker.check(target, data);

        // The correct ERC721TokenReceiver must return the selector 0x150b7a02
        // The buggy version returns 0x00000000
        assertTrue(returned == 0x150b7a02);
    }
}

contract CallbackChecker {
    C immutable c;
    constructor(C _c) { c = _c; }
    function check(address target, bytes calldata data) external returns (bytes4) {
        try c.onERC721Received(target, target, 0, data) returns (bytes4 result) {
            return result;
        } catch {
            return bytes4(0xdeadbeef);
        }
    }
}

